# POST /api/sheets/{sheetId}/bulk-settle — settle the selected claims together. Each selected claim is settled by the
# signed-in user exactly as the single settle does (see ApplyClaimStatus), in list order: people in the order they were
# added, a person's claims newest first; one that goes to PENDING counts as settled, and each writes its own
# CLAIM_SETTLED or CLAIM_PENDING and figure lines. Each that cannot be settled (or is not on the sheet) is left as it is
# and counted refused. Responds with how many were settled and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkSettle
  next: settle
settle:
  class: net.officefloor.hq.app.claim.SettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Settles each selected claim, in list order (people in the order they were added, a person's claims newest first),
 * through the very steps of the single settle: ApplyClaimStatus (its rules, a clerk's settle above the clerk limit
 * making it PENDING), SaveClaimStatus (its status log line) and RecordClaimStatusChanged (CLAIM_SETTLED or
 * CLAIM_PENDING and the figures it moved). A claim made PENDING counts as settled. Each that the single settle would
 * refuse, or is not on the sheet, is left as it is and counted refused. When at least one is settled the settle is the
 * sheet's next batch, marked on each claim it settled.
 */
public class SettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleRequest request, ClaimRepository claims,
            PersonRepository people, RateRepository rates, PeriodRepository periods, SettingRepository settings,
            RoleRepository roles, SheetRepository sheets, WatchRepository watches, Rollup rollup, Audit audit, ClaimLog log,
            VoidReasonRepository voidReasons, Out<BulkSettleResult> result) {
        String sheet = sheetId.trim();
        Set<Long> selected = new HashSet<>(request.claimIds());
        List<Person> listed = people.list(sheet);
        Map<Long, Integer> personOrder = new HashMap<>();
        for (int i = 0; i < listed.size(); i++) {
            personOrder.put(listed.get(i).id(), i);
        }
        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
                .toList();
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.SETTLE, ClaimStatus.SETTLED, request.by(), "");
        ApplyClaimStatus apply = new ApplyClaimStatus();
        SaveClaimStatus save = new SaveClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Long> settled = new ArrayList<>();
        for (Claim listedClaim : chosen) {
            Claim claim = claims.find(sheet, listedClaim.id());
            if (claim == null) {
                continue;
            }
            RollupBefore before = rollup.take(sheet);
            Claim[] changed = new Claim[1];
            Claim[] stored = new Claim[1];
            ClaimNumber[] number = new ClaimNumber[1];
            PreviousDue[] previous = new PreviousDue[1];
            try {
                apply.apply(claim, change, people, rates, periods, settings, roles, sheets, claims, log, voidReasons,
                        (c) -> changed[0] = c, (n) -> number[0] = n, (p) -> previous[0] = p);
                save.save(changed[0], change, claims, periods, settings, sheets, log, voidReasons, (c) -> stored[0] = c,
                        (n) -> number[0] = n);
            } catch (InvalidClaimStatusException refused) {
                continue;
            }
            settled.add(stored[0].id());
            record.record(stored[0], change, number[0], previous[0], people, watches, before, rollup, audit);
        }
        if (!settled.isEmpty()) {
            claims.batch(sheet, settled, sheets.today(sheet));
        }
        result.set(new BulkSettleResult(settled.size(), selected.size() - settled.size()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Objects;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the selected claim ids (each once; a missing list is none) and who settles them. */
public class ValidateBulkSettle {
    public void validate(@RequestBody BulkSettleRequest request, Out<BulkSettleRequest> body) {
        List<Long> ids = request == null || request.claimIds() == null ? List.of()
                : request.claimIds().stream().filter(Objects::nonNull).distinct().toList();
        String by = request == null || request.by() == null ? "" : request.by().trim();
        body.set(new BulkSettleRequest(ids, by));
    }
}
package net.officefloor.hq.app.claim;

/** The outcome of a bulk settle: how many of the selected claims were settled (or made PENDING) and how many refused. */
public record BulkSettleResult(int settled, int refused) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with how many of the selected claims were settled and how many refused. */
public class RespondWithBulkSettle {
    public void respond(@Val BulkSettleResult result, ObjectResponse<BulkSettleResult> response) {
        response.send(result);
    }
}

