            case OPEN -> ClaimStatus.DRAFT;
            case SETTLE -> ClaimStatus.OPEN;
            case APPROVE, REJECT -> ClaimStatus.PENDING;
            case RESETTLE -> ClaimStatus.SETTLED;
            case VOID -> null;
